CREATE FUNCTION public.save_foundation_settings(payload jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.private_access() THEN RAISE EXCEPTION 'Acesso não autorizado'; END IF; UPDATE public.profiles SET name=left(trim(payload->>'name'),100), timezone=payload->>'timezone' WHERE id=auth.uid(); UPDATE public.settings SET timezone=payload->>'timezone', products_per_day=(payload->>'products_per_day')::integer, daily_post_limit=(payload->>'daily_post_limit')::integer, window_start=(payload->>'window_start')::time, window_end=(payload->>'window_end')::time, min_interval_minutes=(payload->>'min_interval_minutes')::integer, story_delay_min_hours=(payload->>'story_delay_min_hours')::integer, story_delay_max_hours=(payload->>'story_delay_max_hours')::integer, repeat_days=(payload->>'repeat_days')::integer, max_attempts=(payload->>'max_attempts')::integer, min_images=(payload->>'min_images')::integer WHERE user_id=auth.uid(); INSERT INTO public.activity_log(user_id,action,result) VALUES(auth.uid(),'Configurações atualizadas','Sucesso'); END $$;
CREATE FUNCTION public.record_foundation_access() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.private_access() THEN RAISE EXCEPTION 'Acesso não autorizado'; END IF; IF NOT EXISTS(SELECT 1 FROM public.activity_log WHERE user_id=auth.uid() AND action='Acesso confirmado' AND created_at>now()-interval '5 minutes') THEN INSERT INTO public.activity_log(user_id,action,result) VALUES(auth.uid(),'Acesso confirmado','Sucesso'); END IF; END $$;
REVOKE ALL ON FUNCTION public.save_foundation_settings(jsonb),public.record_foundation_access() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.save_foundation_settings(jsonb),public.record_foundation_access() TO service_role;